"""Disposable fake-store accounting ownership checks; no external model or service."""
from __future__ import annotations
import asyncio,json,threading
from sandbox_science.orchestrator.consistency.models import ReviewConfig
from sandbox_science.orchestrator.consistency.rubric import RUBRIC_VERSION
from sandbox_science.orchestrator.consistency.runner import ReviewerRunner
from sandbox_science.orchestrator.model import ModelTurn

class Store:
    def __init__(self,blocked):
        self.blocked=blocked;self.entered=threading.Event();self.release=threading.Event();self.exited=threading.Event();self.reserved=0;self.used=0;self.finished=[]
    def run(self,*args):
        return {'config':ReviewConfig(time_seconds=5).model_dump(mode='json'),'rubric':RUBRIC_VERSION,'coverage_complete':True}
    def gate(self,name):
        if self.blocked==name:
            self.entered.set()
            if not self.release.wait(5):raise RuntimeError('scratch probe release timeout')
            self.exited.set()
    def reserve_call(self,*args,**kwargs):
        self.gate('reserve');self.reserved+=1;return 1
    def renew(self,*args,**kwargs):pass
    def call_usage(self,*args,**kwargs):self.gate('usage');self.used+=1
    def finish(self,*args,**kwargs):self.gate('finish');self.finished.append(args[4])

class SyntheticReply:
    """Pure local return value, no provider/transport."""
    async def complete(self,messages,tools):
        return ModelTurn('{"outcome":"inconclusive","summary":"Synthetic","cap_reached":false}')

async def entered(store):
    async with asyncio.timeout(2):
        while not store.entered.is_set():await asyncio.sleep(.005)

async def case(name):
    store=Store(name)
    runner=ReviewerRunner(store,'p','s','rev-'+'1'*24,'owner',None if name=='finish' else SyntheticReply())
    task=asyncio.create_task(runner.run())
    try:
        await entered(store)
        task.cancel();await asyncio.sleep(.02);task.cancel();await asyncio.sleep(.02)
        held=not task.done();assert held,(name,'runner returned before actual blocked SQL exited')
        assert not store.exited.is_set()
        store.release.set()
        outcome=await asyncio.gather(task,return_exceptions=True)
        assert isinstance(outcome[0],asyncio.CancelledError),(name,type(outcome[0]).__name__)
        assert store.exited.is_set()
        assert store.reserved==(0 if name=='finish' else 1)
        assert store.used==(1 if name=='usage' else 0)
        assert store.finished==(['failed'] if name=='finish' else ['dropped'])
        return {'case':name,'retained_until_thread_exit':held,'reserved':store.reserved,'used':store.used,'finish':store.finished}
    finally:
        store.release.set()
        if not task.done():task.cancel()
        await asyncio.gather(task,return_exceptions=True)
        async with asyncio.timeout(2):
            while not store.exited.is_set():await asyncio.sleep(.005)

async def main():
    for name in ('reserve','usage','finish'):print(json.dumps(await case(name)))
if __name__=='__main__':asyncio.run(main())
